/**
 * Habit accessories: things a pet starts wearing because of how you eat.
 *
 * Nothing here is stored. Each accessory is worked out from the food journal (getPetJournal), so it
 * needs no API or database change, and it goes away again if the meals that earned it are deleted.
 *
 * The drawings live in public/pets/accessories/<pet>-<accessory>.png and are generated by
 * scripts/pets/pets.html. Only the pets listed in ART have drawings so far.
 */
import { useSyncExternalStore } from 'react';
import { getPetJournal } from './api.js';

const bostonHour = (iso) =>
  Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: 'numeric', hourCycle: 'h23' }).format(new Date(iso)));

/**
 * Each habit: which meals count toward it, how many a pet needs, and how to say why it is wearing it.
 * `key` makes a habit count different things instead of meals (the chef's hat counts kinds of food).
 * Two accessories with the same `slot` cannot be worn together: the pet keeps the one it earned last.
 */
export const HABITS = {
  nightcap: {
    label: 'Nightcap',
    slot: 'head',
    need: { starter: 2, pet: 1 },
    counts: (entry) => {
      const h = bostonHour(entry.visited_at);
      return h >= 22 || h < 4;
    },
    why: (n) => `${n} late-night ${n === 1 ? 'meal' : 'meals'} (after 10 pm)`,
  },
  chef: {
    label: "Chef's hat",
    slot: 'head',
    need: { starter: 7, pet: 2 },
    counts: (entry) => Boolean(entry.place?.cuisine),
    key: (entry) => entry.place.cuisine,
    why: (n) => `${n} different kinds of food`,
  },
  coffee: {
    label: 'Coffee cup',
    need: { starter: 2, pet: 1 },
    counts: (entry) => /cafe|café|coffee|tea|bakery/i.test(entry.place?.cuisine ?? ''),
    why: (n) => `${n} cafe ${n === 1 ? 'visit' : 'visits'}`,
  },
};

/** Which accessories have been drawn for which pet. */
const ART = {
  starter: ['nightcap', 'chef', 'coffee'],
  'back-bay': ['nightcap', 'chef', 'coffee'],
  cambridge: ['coffee'],
};

/**
 * How far along a habit is, and when it was earned (the meal that reached the target).
 * The starter eats everywhere, so its targets are higher than a neighborhood pet's.
 */
function progress(habit, petId, entries) {
  const need = petId === 'starter' ? habit.need.starter : habit.need.pet;
  const seen = new Set();
  let earnedAt = null;
  for (const e of [...entries].sort((a, b) => a.visited_at.localeCompare(b.visited_at))) {
    if (!habit.counts(e)) continue;
    seen.add(habit.key ? habit.key(e) : e.id ?? seen.size);
    if (!earnedAt && seen.size >= need) earnedAt = e.visited_at;
  }
  return { n: seen.size, earnedAt };
}

/**
 * @param {Array} entries every meal, with `place` (from getPetJournal('starter'))
 * @returns {Record<string, Array<{id: string, label: string, image: string, why: string, worn: boolean}>>} by pet id.
 *   `worn` is false for something the pet has earned but took off for a newer one in the same slot.
 */
export function accessoriesFor(entries) {
  const out = {};
  for (const [petId, ids] of Object.entries(ART)) {
    const mine = petId === 'starter' ? entries : entries.filter((e) => e.place?.neighborhood?.id === petId);
    const earned = [];
    for (const id of ids) {
      const habit = HABITS[id];
      const { n, earnedAt } = progress(habit, petId, mine);
      if (earnedAt) {
        earned.push({ id, label: habit.label, slot: habit.slot, earnedAt, image: `/pets/accessories/${petId}-${id}.png`, why: habit.why(n) });
      }
    }
    earned.forEach((a, i) => {
      // Newest wins; if one meal earned both, the later one in ART wins.
      const newer = (b, j) => b.earnedAt > a.earnedAt || (b.earnedAt === a.earnedAt && j > i);
      a.worn = !a.slot || !earned.some((b, j) => j !== i && b.slot === a.slot && newer(b, j));
    });
    if (earned.length) out[petId] = earned.sort((a, b) => Number(b.worn) - Number(a.worn));
  }
  return out;
}

/* A tiny shared store, so every drawing of a pet shows the same accessories without each screen fetching them. */
let current = {};
let loaded = false;
const listeners = new Set();

export async function refreshAccessories() {
  loaded = true;
  try {
    const journal = await getPetJournal('starter');
    current = accessoriesFor(journal.entries);
  } catch {
    current = {};
  }
  listeners.forEach((fn) => fn());
}

const subscribe = (fn) => {
  listeners.add(fn);
  if (!loaded) refreshAccessories();
  return () => listeners.delete(fn);
};
const NONE = [];

/** What a pet has earned; the ones with `worn` are drawn on it. */
export function usePetAccessories(petId) {
  const all = useSyncExternalStore(subscribe, () => current);
  return all[petId] ?? NONE;
}
